pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _test(uint256 _val1, uint256 _val2) internal {
        vm.assume(_val1 != _val2);
        try c.SetMinSum(_val1) {} catch { return; }
        try c.SetMinSum(_val2) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        assertTrue(minSumAfter == _val2);
    }

    function testFuzz_test(uint256 _val1, uint256 _val2) public {
        _test(_val1, _val2);
    }

    receive() external payable {}
}
